        if($path!==null)foreach($rows as$d)if(self::path($d)===rtrim($path,'/'))$selectedId=$d['id'];
        $selected=null;if($path!==null&&$selectedId!==null){$selected=[];foreach($rows as$d)if($d['id']===$selectedId){$selected[$d['locale'].':'.$d['id']]=true;if($d['authorId']!=='')$selected[$d['locale'].':'.$d['authorId']]=true;foreach($d['links']as$link)if($link['kind']==='growth')$selected[$d['locale'].':'.$link['id']]=true;}}
        $known=[];foreach($catalog['apps']as$app)$known[$app['id']]=true;$out=[];
        foreach($rows as$d){if($selected!==null&&!isset($selected[$d['locale'].':'.$d['id']]))continue;$visible=true;foreach($d['appIds']as$id){if(!array_key_exists($id,$known)){$r=$this->repo->record('app',$id);$known[$id]=$r&&Localization::published($r)&&Admission::evaluate($r['data'],$this->repo->getAdmissionRules(),$r['admissionException']??'')['accepted'];}if(!$known[$id]){$visible=false;break;}}if(!$visible)continue;$d=$this->present($d);unset($d['reviewNote']);$out[]=$d;}return$out;
    }
    public static function approved(array$d):bool{return$d['status']==='published'&&!empty($d['seoApproved'])&&empty($d['stale'])&&empty($d['seo']['noindex']);}
