        $docs=array_map(fn($d)=>$this->present($d),$this->rows());$groups=[];$in=[];$edges=[];$warnings=[];foreach($docs as$d){$key=$d['locale'].':'.mb_strtolower(trim($d['topic'].'|'.$d['intent']));if($d['topic']!==''||$d['intent']!=='')$groups[$key][]=$d['id'];$node=$d['locale'].':'.$d['id'];$in[$node]??=0;foreach($d['links']as$link){$to=$d['locale'].':'.$link['kind'].':'.$link['id'];$edges[]=['from'=>$node,'to'=>$to,'label'=>$link['label']];if($link['kind']==='growth')$in[$d['locale'].':'.$link['id']]=($in[$d['locale'].':'.$link['id']]??0)+1;}if($d['authorId']!=='')$in[$d['locale'].':'.$d['authorId']]=($in[$d['locale'].':'.$d['authorId']]??0)+1;if(!empty($d['stale']))$warnings[]=['code'=>'stale-source','id'=>$d['id'],'locale'=>$d['locale'],'message'=>'Linked app data changed; review and approve again.'];}
