    public function lifecycle():array{return$this->repo->setting('growth-lifecycle',['revision'=>0,'rules'=>[]]);}
    public static function localPath(mixed$p):string{Validation::check(is_string($p)&&strlen($p)<=500&&preg_match('~^/(?:[A-Za-z0-9_-]+/?)*$~D',$p)&&$p!=='/'&&!preg_match('~^/(?:api|assets|media|storage|app|resources|client|cli|install|admin|kurulum|yonetim)(?:/|$)~',$p),'Invalid or protected lifecycle path.');return rtrim($p,'/');}
