    public function importGsc(array$v):array{$import=self::parseGsc($v);return$this->repo->transaction(function()use($import){$state=$this->repo->setting('growth-gsc',['imports'=>[]]);array_unshift($state['imports'],$import);$state['imports']=array_slice($state['imports'],0,5);$this->repo->setSetting('growth-gsc',$state);$this->repo->audit('growth-gsc','csv','rows='.count($import['rows']));return$state;});}
