    }
    public function restoreBackup(array$b):void{
        $b=self::validateBackup($b);self::migrate($this->db);$this->db->exec('DELETE FROM ws_growth_documents');$this->db->exec('DELETE FROM ws_growth_revisions');foreach($b['revisions']as$d)$this->query('INSERT INTO ws_growth_revisions(id,locale,revision,payload) VALUES(?,?,?,?)',[$d['id'],$d['locale'],$d['revision'],self::json($d)]);foreach($b['documents']as$d){$this->query('INSERT INTO ws_growth_documents(id,locale,kind,slug,revision,payload) VALUES(?,?,?,?,?,?)',[$d['id'],$d['locale'],$d['kind'],$d['slug'],$d['revision'],self::json($d)]);if(!$this->query('SELECT revision FROM ws_growth_revisions WHERE id=? AND locale=? AND revision=?',[$d['id'],$d['locale'],$d['revision']])->fetchColumn())$this->query('INSERT INTO ws_growth_revisions(id,locale,revision,payload) VALUES(?,?,?,?)',[$d['id'],$d['locale'],$d['revision'],self::json($d)]);}$this->repo->setSetting('growth-lifecycle',$b['lifecycle']);$this->repo->setSetting('growth-gsc',$b['gsc']);
    }
}
